<template>
  <div class="document-editor-shell" @keydown.meta.s.prevent="saveNow" @keydown.ctrl.s.prevent="saveNow">
    <header class="editor-bar">
      <button class="back" type="button" @click="emit('back')"><span v-html="icons.arrowLeft" /> Files</button>
      <div class="file-switcher" role="tablist" aria-label="Open files">
        <button v-for="file in files" :key="file.id" type="button" role="tab" :aria-selected="file.id===item.id" :class="{active:file.id===item.id}" @click="emit('select',file)">
          <span class="type-mark">{{ editorTypeForPath(file.path)?.id==='markdown'?'M':'T' }}</span>{{ file.path.split('/').at(-1) }}
        </button>
      </div>
      <div class="bar-spacer" />
      <span class="save-chip" :class="saveState"><i />{{ saveLabel }}</span>
      <div class="presence" aria-label="Present collaborators"><span>{{ ownerInitial }}</span><span>S</span></div>
      <button class="icon-button" type="button" title="History" :aria-pressed="drawer==='history'" @click="toggleDrawer('history')" v-html="icons.history" />
      <button class="icon-button" type="button" title="Links" :aria-pressed="drawer==='links'" @click="toggleDrawer('links')" v-html="icons.link" />
      <button class="icon-button" type="button" title="More" v-html="icons.more" />
    </header>

    <div v-if="loading" class="editor-state">Loading document…</div>
    <div v-else-if="loadError" class="editor-state error">{{ loadError }} <button type="button" @click="load()">Retry</button></div>
    <template v-else>
      <main class="paper-sheet">
        <div class="cover" />
        <h1>{{ title }}</h1>
        <div class="properties">
          <span class="property"><b>{{ editorType.label }}</b> {{ fileName }}</span>
          <button v-for="(value,key) in properties" :key="key" type="button" class="property" :disabled="readOnly" @click="area?.revealProperties?.()">{{ key }} <b>{{ value }}</b></button>
          <span v-if="readOnly" class="property readonly">Read only</span>
        </div>
        <component :is="editorType.component" ref="area" v-model="content" :read-only="readOnly" @update:model-value="queueSave" />
        <button v-if="editorType.id==='markdown' && !readOnly" class="slash-button" type="button" @click="slashOpen=!slashOpen"><span>/</span> Insert block</button>
        <div v-if="slashOpen" class="slash-menu" role="menu">
          <section><h2>Components</h2><button v-for="entry in componentEntries" :key="entry.label" type="button" disabled><span v-html="entry.icon" /><b>{{ entry.label }}</b></button></section>
          <section><h2>Layout</h2><button type="button" @click="insertMarkdown('## Heading\n')"><span v-html="icons.heading" /><b>Heading</b></button><button type="button" @click="insertMarkdown('- List item\n')"><span v-html="icons.list" /><b>List</b></button><button type="button" @click="insertMarkdown('- [ ] Task\n')"><span v-html="icons.check" /><b>Checklist</b></button><button type="button" @click="insertMarkdown('| Column | Column |\n| --- | --- |\n|  |  |\n')"><span v-html="icons.table" /><b>Table</b></button><button type="button" @click="insertMarkdown('<details>\n<summary>Toggle</summary>\n\n</details>\n')"><span v-html="icons.toggle" /><b>Toggle</b></button></section>
          <section><h2>Link</h2><button type="button" @click="insertMarkdown('[link](https://)')"><span v-html="icons.link" /><b>Link</b></button></section>
        </div>
      </main>
      <aside v-if="drawer" class="drawer">
        <div class="drawer-heading"><h2>{{ drawer==='history'?'History':'Links' }}</h2><button type="button" aria-label="Close drawer" @click="drawer=null">×</button></div>
        <template v-if="drawer==='history'"><p v-if="drawerLoading">Loading versions…</p><article v-for="version in versions" :key="version.id"><b>{{ version.versionNumber ? `v${version.versionNumber}` : shortVersion(version.id) }}</b><span>{{ version.created_by_id }}</span><small>{{ formatDate(version.created_at) }}<template v-if="version.message"> · {{ version.message }}</template></small></article><p v-if="!drawerLoading&&!versions.length">No earlier versions.</p></template>
        <template v-else><p v-if="drawerLoading">Loading links…</p><article v-for="link in links" :key="link.id"><b>{{ link.path.split('/').at(-1) }}</b><span>{{ link.kind.replace('_',' ') }}</span><small>{{ link.direction }}</small></article><p v-if="!drawerLoading&&!links.length">No links yet.</p></template>
      </aside>
      <div v-if="conflict" class="conflict-banner" role="alert"><b>This file changed elsewhere.</b><span>Your text is still here.</span><button type="button" @click="reloadLatest">Reload latest</button><button type="button" class="primary" @click="keepMine">Keep mine</button></div>
      <div v-else-if="saveError" class="conflict-banner error" role="alert"><b>Couldn't save.</b><span>{{ saveError }}</span><button type="button" @click="saveNow">Try again</button></div>
    </template>
  </div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { editorTypeForPath } from './registry';
import type { FilesDataSource, FilesDetail, FilesItem, FilesVersion } from '../types';
const props=defineProps<{ dataSource:FilesDataSource; item:FilesItem; files:FilesItem[] }>();
const emit=defineEmits<{ back:[]; select:[item:FilesItem]; saved:[item:FilesItem] }>();
const area=ref<{revealProperties?:()=>void}|null>(null);
const loading=ref(true), loadError=ref(''), content=ref(''), baseVersionId=ref(''), saveState=ref<'saved'|'saving'|'merged'|'conflict'|'error'>('saved'), saveError=ref(''), conflict=ref<{currentVersionId:string}|null>(null), slashOpen=ref(false), drawer=ref<'history'|'links'|null>(null), drawerLoading=ref(false), versions=ref<FilesVersion[]>([]), detail=ref<FilesDetail|null>(null); let timer:ReturnType<typeof setTimeout>|undefined;
const editorType=computed(()=>editorTypeForPath(props.item.path)!); const fileName=computed(()=>props.item.path.split('/').at(-1)??props.item.path); const title=computed(()=>fileName.value.replace(/\.sulla\.md$|\.(?:md|txt)$/i,'').replace(/[-_]+/g,' ')); const properties=computed(()=>editorType.value.parse(content.value).properties); const readOnly=computed(()=>detail.value?.capabilities?.canEdit===false); const ownerInitial=computed(()=>(props.item.ownerDisplayName||'J').trim()[0]?.toUpperCase()||'J'); const links=computed(()=>detail.value?.links??[]);
const saveLabel=computed(()=>saveState.value==='saving'?'Saving…':saveState.value==='merged'?`Merged · ${shortVersion(baseVersionId.value)}`:saveState.value==='conflict'?'Conflict':saveState.value==='error'?'Not saved':`Saved · ${shortVersion(baseVersionId.value)}`);
const icons={arrowLeft:'<svg viewBox="0 0 24 24"><path d="m15 18-6-6 6-6"/></svg>',history:'<svg viewBox="0 0 24 24"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/></svg>',link:'<svg viewBox="0 0 24 24"><path d="M10 13a5 5 0 0 0 7.5.5l2-2a5 5 0 0 0-7-7l-1.1 1.1M14 11a5 5 0 0 0-7.5-.5l-2 2a5 5 0 0 0 7 7l1.1-1.1"/></svg>',more:'<svg viewBox="0 0 24 24"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg>',heading:'<svg viewBox="0 0 24 24"><path d="M5 4v16M19 4v16M5 12h14"/></svg>',list:'<svg viewBox="0 0 24 24"><path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></svg>',check:'<svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 12 3 3 7-7"/></svg>',table:'<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M9 4v16"/></svg>',toggle:'<svg viewBox="0 0 24 24"><path d="m9 18 6-6-6-6"/></svg>'};
const componentEntries=[{label:'Chart',icon:icons.table},{label:'Sulla component',icon:icons.check}];
function shortVersion(value:string){return value?`v${value.replace(/^version-/,'').slice(0,8)}`:'v—'} function formatDate(value:string){return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
async function load(versionId?:string){loading.value=true;loadError.value='';clearTimeout(timer);pendingSave=false;try{const metadata=await props.dataSource.detail(props.item.id);const loadedVersion=versionId||metadata.version?.id||props.item.currentVersionId;const preview=await props.dataSource.preview(props.item.id,loadedVersion);content.value=new TextDecoder().decode(preview.data);baseVersionId.value=loadedVersion;detail.value=metadata;saveState.value='saved';conflict.value=null}catch(cause){loadError.value=cause instanceof Error?cause.message:String(cause)}finally{loading.value=false}}
function queueSave(){if(readOnly.value)return;saveState.value='saving';conflict.value=null;saveError.value='';clearTimeout(timer);timer=setTimeout(saveNow,850)}
// Single-range diff: enough to tell whether two edits touch the same span.
function rangeDiff(from:string,to:string){let start=0;while(start<from.length&&start<to.length&&from[start]===to[start])start++;let end=0;while(end<from.length-start&&end<to.length-start&&from[from.length-1-end]===to[to.length-1-end])end++;return{from:start,to:from.length-end,insert:to.slice(start,to.length-end)}}
// Applies the server's merged changes on top of text typed while the save was in flight; null when both touched the same span.
function rebase(sent:string,merged:string,local:string):string|null{if(local===sent)return merged;const theirs=rangeDiff(sent,merged),mine=rangeDiff(sent,local);if(theirs.to<=mine.from)return local.slice(0,theirs.from)+theirs.insert+local.slice(theirs.to);if(theirs.from>=mine.to){const shift=mine.insert.length-(mine.to-mine.from);return local.slice(0,theirs.from+shift)+theirs.insert+local.slice(theirs.to+shift)}return null}
let saving=false,pendingSave=false;
async function saveNow(){clearTimeout(timer);if(readOnly.value||loading.value)return;if(saving){pendingSave=true;return}saving=true;pendingSave=false;saveState.value='saving';saveError.value='';const sent=content.value;try{const result=await props.dataSource.saveContent({fileId:props.item.id,baseVersionId:baseVersionId.value,content:editorType.value.serialize({content:sent,properties:editorType.value.parse(sent).properties})});if(result.status==='merged'){const next=rebase(sent,result.content,content.value);if(next===null){conflict.value={currentVersionId:result.versionId};saveState.value='conflict';return}baseVersionId.value=result.versionId;if(next!==content.value)content.value=next;if(next!==result.content)pendingSave=true}else{baseVersionId.value=result.versionId;if(content.value!==sent)pendingSave=true}saveState.value=pendingSave?'saving':result.status;conflict.value=null;emit('saved',{...props.item,currentVersionId:result.versionId,updatedAt:new Date().toISOString()})}catch(cause){const error=cause as Error&{code?:string;currentVersionId?:string;status?:number};if(error.code==='VERSION_CONFLICT'||error.status===409){conflict.value={currentVersionId:error.currentVersionId||''};saveState.value='conflict'}else{saveError.value=error.message||String(cause);saveState.value='error'}}finally{saving=false;if(pendingSave&&!conflict.value)void saveNow()}}
async function reloadLatest(){const versionId=conflict.value?.currentVersionId||props.item.currentVersionId;await load(versionId)}
async function keepMine(){if(conflict.value?.currentVersionId)baseVersionId.value=conflict.value.currentVersionId;conflict.value=null;await saveNow()}
